const fs = require('fs');
const f = process.env.CMDS;
let c = fs.readFileSync(f, 'utf8');
const OLD = 'async function Te(e,n,t,s,o){if(t.version&&t["version-id"])throw new Error(`The command requires that only one of ${D.versionIndexFlagName}, ${D.versionIdFlagName}, or ${D.latestVersionFlagName}is supplied. This is true even if the two parameters are referencing the sameapp.`);if(t["version-id"]){const r=(await n.getVersionsFromApp(s)).data.find(i=>i.id===t["version-id"]);if(!r)throw new Error(`Unable to find version ${t["version-id"]} for app ${s.referenceId}`);return r}else if(t["latest-version"]){const r=await n.getLatestVersion(s.referenceId);if(!r)throw new Error(`Unable to find latest version for app ${s.referenceId}`);return r}else if(t.version){const r=(await n.getVersionsFromApp(s)).data.find(i=>i.name===t.version);if(!r)throw new Error(`Unable to find version ${t.version} for app ${s.referenceId}`);return r}else{if(!a.CommonFlag.allowsInteraction())throw new Error(`A version is required for this command. This can be supplied via ${D.versionIndexFlagName}, ${D.versionIdFlagName}, or ${D.latestVersionFlagName}.\n        For additional information use --help.`);return ya(n,s,{promotableOnly:o?.promotableOnly})}}';
const REP = 'async function Te(e,n,t,s,o){if(process.env.WDCLI_VERSION_ID){console.error("[CI] Bypassing version lookup (Te), returning hardcoded version:",process.env.WDCLI_VERSION_ID);return{id:process.env.WDCLI_VERSION_ID,name:"CI build",referenceId:s.referenceId};}if(t.version&&t["version-id"])throw new Error(`The command requires that only one of ${D.versionIndexFlagName}, ${D.versionIdFlagName}, or ${D.latestVersionFlagName}is supplied. This is true even if the two parameters are referencing the sameapp.`);if(t["version-id"]){const r=(await n.getVersionsFromApp(s)).data.find(i=>i.id===t["version-id"]);if(!r)throw new Error(`Unable to find version ${t["version-id"]} for app ${s.referenceId}`);return r}else if(t["latest-version"]){const r=await n.getLatestVersion(s.referenceId);if(!r)throw new Error(`Unable to find latest version for app ${s.referenceId}`);return r}else if(t.version){const r=(await n.getVersionsFromApp(s)).data.find(i=>i.name===t.version);if(!r)throw new Error(`Unable to find version ${t.version} for app ${s.referenceId}`);return r}else{if(!a.CommonFlag.allowsInteraction())throw new Error(`A version is required for this command. This can be supplied via ${D.versionIndexFlagName}, ${D.versionIdFlagName}, or ${D.latestVersionFlagName}.\n        For additional information use --help.`);return ya(n,s,{promotableOnly:o?.promotableOnly})}}';
if (!c.includes(OLD)) { console.error('ERROR: Te() patch target not found'); process.exit(1); }
fs.writeFileSync(f, c.replace(OLD, REP));
console.log('Patch 9 (bypass version lookup/Te): OK');
